/* guide.js — the Guide: everything this site shows and explains, in one place, on a computer or a phone. Its
   chapters go from getting around to the electrons in a transistor; the models are listed from the gallery's own
   data and the terms from the glossary's, so it names every one of them. One search runs over all of it, and a
   section can open what it describes. Text about clicking says the right thing for a mouse or a touch screen. */
(function (NA) {
  'use strict';
  const { el, clear } = NA;
  const App = NA.app;
  const G = { open: false };
  const touch = () => !!(NA.touchFirst && NA.touchFirst());
  // a paragraph is a string, or { mouse, touch }: said the way that suits this device
  const say = (p) => (typeof p === 'string' ? p : touch() ? p.touch : p.mouse);

  // ------------------------------------------------------------------ opening what a section describes
  const presets = () => NA.presets.byId;
  // wait for a condition (a model to be on screen), then act; gives up quietly after a few seconds
  const when = (ok, then, tries = 75) => { if (ok()) then(); else if (tries > 0) setTimeout(() => when(ok, then, tries - 1), 80); };
  const isOn = (id) => () => App.preset && App.preset.id === id && (!presets()[id].lab || (NA.labHost.lab && NA.labHost.lab.ui));
  const load = (id, then) => {
    G.close();
    if (!(App.preset && App.preset.id === id)) App.loadPreset(id);
    if (then) when(isOn(id), () => setTimeout(then, 60));
  };
  // a lab's view (its Architecture, its Growth), whichever way that lab switches its views; in a network model
  // the Growth view is a tab of the explanations
  const show = (id, v) => load(id, () => {
    const L = presets()[id].lab ? NA.labHost.lab : null;
    if (!L) { if (NA.mobile && NA.mobile.mobile) NA.mobile.go('insp'); App.emit('tab', v); return; }
    if (NA.mobile && NA.mobile.mobile) NA.mobile.go('network');
    if (L.setCenterView) L.setCenterView(v);
    else if (L.setView) L.setView(v);
    else if (L.layoutCenter) { L.centerView = v; L.layoutCenter(); }
  });
  const arch = (id) => show(id, 'arch');
  const growth = (id) => show(id, 'growth');
  // a neuron of a network model, opened: its levels down to the transistors
  const neuron = (id = 'spiral', l = 1, j = 0) => load(id, () => when(() => NA.netView && NA.netView.layout, () => NA.netDeep && NA.netDeep.openNeuron(l, j)));
  const scale = () => load('spiral', () => when(() => NA.netView && NA.netView.layout, () => { if (NA.mobile && NA.mobile.mobile) NA.mobile.go('network'); setTimeout(() => NA.scaleView && NA.scaleView.show(), 120); }));
  const lab = (id, fn) => load(id, () => fn(NA.labHost.lab));
  const open = (id) => ['Open ' + presets()[id].name, () => load(id)];
  // a reward world of the model builder, opened (its problem picked)
  const world = (label, id) => [label, () => lab('builder', (L) => L.setProblem(id))];
  // the ways a builder network learns from rewards, named from builder-rl.js's own list
  const METHOD_WORDS = { dqn: 'DQN', pg: 'REINFORCE', a2c: 'actor-critic', ppo: 'PPO', ga: 'a genetic algorithm', novelty: 'novelty search', es: 'evolution strategies', cem: 'the cross-entropy method', me: 'MAP-Elites', erl: 'evolutionary RL (a genetic algorithm and a DQN together)', bc: 'copying your own moves (behaviour cloning)', neat: 'NEAT (networks that grow their own structure)', gauss: 'PPO with a Gaussian policy (for controls that are numbers)', sac: 'SAC (soft actor-critic)', td3: 'TD3 (twin delayed DDPG)', pref: 'your answers to “which did better?” (learning from preferences, the idea behind RLHF)' };
  const rlMethods = () => {
    const B = NA.brl, ids = B ? (B.ORDER || Object.keys(B.METHODS)).filter((m) => B.METHODS[m]) : Object.keys(METHOD_WORDS);
    const words = ids.map((m) => METHOD_WORDS[m] || B.METHODS[m].short);
    return words.length > 1 ? `${words.slice(0, -1).join(', ')} or ${words[words.length - 1]}` : words.join('');
  };

  // ------------------------------------------------------------------ the chapters
  const tap = (lower) => (touch() ? (lower ? 'tap' : 'Tap') : (lower ? 'click' : 'Click'));
  const CHAPTERS = [
    { id: 'start', title: 'Getting around', sections: () => [
      { title: 'What this site is', paras: ['An interactive lab for neural networks. Pick a model, train it right here, and watch what every neuron computes and how it learns. Then zoom into any part of it: a neuron opens into its weighted sum and its code, and the numbers open into their bits, the adders and logic gates that compute with them, the transistors that make the gates, and the electrons in a transistor’s channel.',
        'Every model trains and runs in your browser, on your own device. Most open already trained, with notes on what to look for and experiments to try; nothing needs installing.'],
      acts: [['Open the gallery', () => { G.close(); NA.chrome.openZoo(); }]] },
      { title: 'Picking a model', paras: ['The model name at the top opens the gallery: every model of the site, in groups from Foundations to Reinforcement learning, each with a small picture of what it does. The Models chapter of this Guide lists them all with what each one shows.',
        'The network models (the first groups) share one page: the network in the middle, the data and its maps beside it, the explanations on the right. The labs (a transformer, a diffusion model, an object detector and more) each have a page of their own with an Architecture view.'] },
      { title: 'Training', paras: ['The play button trains and pauses (Space), the step button applies one training step (S), the fast-forward button trains 500 more steps quickly, and the reset button starts again from new random weights (R). The settings button (the sliders) holds the learning rate, the optimizer, the batch size and the rest. The labs have the same controls for their own training.',
        'Once a model is trained, Run held-out test (T) scores it on examples it never saw while training: the honest measure of how well it learned.'] },
      { title: 'Seeing what a part is, and opening it', paras: [
        { mouse: 'Point at a neuron or a connection to see what it computes. Click it to select it: the panel on the right explains it. In a zoom view, click a part to see what it is, with its code; double-click it, zoom in on it, or press Enter to open it. Esc or Backspace goes back one level, and the path at the top goes back further. The mouse wheel zooms and dragging pans.',
          touch: 'Tap a neuron, or a part of any zoom view, to open it. To see what it is instead, hold a finger on it for half a second: a ring fills under your finger, then the explanation opens. Pinch to zoom, drag to pan, and use ← or the path at the top to go back.' },
        { mouse: 'On a touch screen it is the other way round: a tap opens, holding a finger on a part shows it.', touch: 'With a mouse it is the other way round: a click shows a part, a double-click opens it.' }] },
      { title: 'On a phone', paras: ['The page shows one screen at a time: the bar at the bottom switches between the diagram, the data and the explanations (Network, Output and Inspect for a network model; each lab has its own three, such as Board, Agent and Inspect in the reinforcement learning lab). The settings open as a sheet from the sliders button.',
        'To keep the site like an app: in Safari tap Share, then Add to Home Screen; on Android open the browser menu and tap Install app.'] },
      { title: 'Sharing a model', paras: ['The link button copies a link to the model on screen with its settings, so whoever opens it sees the same model the same way.'] },
      { title: 'Help, the tour and the glossary', paras: ['? opens how to read the network and the keyboard shortcuts. From there, Take the tour points at each part of the page in turn, and Glossary lists every term the site uses. In the notes, a quietly underlined word is a glossary term: ' + tap(true) + ' it for its definition.'],
        acts: [['Take the tour', () => { G.close(); NA.tour && NA.tour.start(); }], ['Open the glossary', () => { G.close(); NA.glossary && NA.glossary.open(); }]] },
    ] },
    { id: 'learn', title: 'How a network learns', sections: () => [
      { title: 'A neuron', paras: ['A neuron multiplies each input by a weight, adds them up with a bias, and passes the sum through an activation function. One neuron can only draw one straight line across its inputs: Single Neuron shows that line turning and sliding as the weights learn.'], acts: [open('neuron')] },
      { title: 'Activation functions', paras: ['The activation bends the sum. ReLU keeps a positive sum and turns a negative one into 0; tanh and sigmoid squash it into a range; others sit in between. Without a bend, any stack of layers would still draw only straight lines. The chip under each layer picks its function, and a selected neuron can have its own.'] },
      { title: 'Hidden layers and depth', paras: ['Hidden layers combine simple pieces into complicated ones. XOR cannot be split by one line, so it needs a hidden layer; with ReLU each hidden neuron folds the plane along one line, and the folds add up to a polygon (ReLU Polygon). Deeper layers build features out of features, enough to untangle a spiral (Deep Spiral).'], acts: [open('xor'), open('ring'), open('spiral')] },
      { title: 'Outputs and the loss', paras: ['The output layer turns the last sums into a prediction: softmax gives a probability for each class (Three Classes), a single sigmoid a yes or no, and a plain sum a number. The loss scores how wrong the prediction is: cross-entropy for classes, squared error for numbers. Training is nothing but making the loss smaller.'], acts: [open('pinwheel')] },
      { title: 'Gradients and backpropagation', paras: ['For every weight, the gradient says how much the loss would change if that weight moved a little. Backpropagation works out all of them in one backward pass, applying the chain rule from the output back toward the input. The Backprop tab walks through one training step phase by phase, with the real numbers; the gradient lenses show the same on the diagram, in violet.'] },
      { title: 'Gradient descent and optimizers', paras: ['Each step moves every weight a little against its gradient; the learning rate sets how far. SGD follows the gradient of a small batch of examples, momentum keeps a running velocity so steady directions speed up, and Adam scales each weight’s step by the size of its own recent gradients. The loss landscape shows the path the weights took.'] },
      { title: 'Batches, epochs, validation and test', paras: ['A batch is the handful of examples one step learns from; an epoch is one pass through all of them. Part of the data is held back. The validation set is scored while training, to show how well the model does on examples it does not learn from; the held-out test set is scored only when you run the test, once you have finished changing things.'] },
      { title: 'Fitting a curve', paras: ['A network can approximate any curve. With ReLU, each hidden neuron adds one kink, and the output adds the pieces up: Curve Fitting builds a wave that way.'], acts: [open('sine')] },
      { title: 'Learning to see', paras: ['Digit Recognizer reads handwritten digits from their pixels. Its hidden neurons learn stroke templates, a loop here and a bar there, which the Maps lens draws inside each neuron.'], acts: [open('digits')] },
      { title: 'When training goes wrong', paras: ['Overfitting: the model learns the training examples, noise and all, and does worse on new ones; validation loss rises while training loss falls. L2 regularization, dropout and early stopping fight it (Overfitting).',
        'Vanishing gradients: in a deep stack of sigmoid layers the gradient shrinks at every layer on its way back, and the early layers barely learn (Vanishing Gradients). Dead ReLUs (always 0, so they never learn), saturated neurons (stuck on a flat tail) and steps that blow up show in the Health lens and in Insights, with what to do about them.'], acts: [open('overfit'), open('vanishing')] },
      { title: 'Watching it learn: Growth', paras: [
        'Every model can show how it learned: the Growth tab of the network models, and the Growth view of each lab, the model builder and the reinforcement learning examples. It keeps a film of the training, a moment each time the count of steps passes 1, 2, 5, 10, 20… (a log scale: a model changes fastest at the start). Play runs the moments as a timelapse; the strip, the slider and the learning curve pick one. A model trained in advance learns again from scratch for its film.',
        'The curve names the stages it went through: warming up, learning fast and polishing, and where they show, memorising (validation getting worse while training improves) or slipping back (a policy forgetting what worked). Inside it draws how big each layer’s weights are and how far they have moved from their start. The math at each moment writes out the loss, the rule of one training step (gradient descent, momentum, Adam, or the update of Q-learning, a policy gradient or evolution) and the numbers it used then: the loss, the learning rate, the size of the gradient, the change since the moment before. YOLO26 and the radar classifier trained offline in PyTorch: their films are their training logs, a moment per epoch.'],
        acts: [['Growth in Overfitting', () => growth('overfit')], ['Growth in the transformer', () => growth('transformer')], ['Growth in Maze Runner', () => growth('rl-maze')]] },
    ] },
    { id: 'read', title: 'Reading the network', sections: () => [
      { title: 'Colours', paras: ['Blue is positive and orange is negative everywhere: weights, activations, signals, and the two classes of a yes-or-no problem. Violet measures gradients: the pressure on a number to change.'] },
      { title: 'Lenses', paras: ['The connections can show their weights, the signal flowing through them for the current input, or their gradients (keys 1, 2, 3); the neurons their output, their sum before the activation, or their gradient (4, 5, 6).',
        'Maps (M) draws inside each neuron what it outputs for every possible input, so you can watch simple shapes in the first layer combine into complicated ones deeper in. Values (V), Bias (B), Flow (F), Functions (A) and Health (H) add the numbers, the biases, the signal flowing through, each neuron’s function, and warnings about neurons in trouble.'] },
      { title: 'The probe and the output map', paras: [{ mouse: 'One input is always being traced through the network: the probe. Hover over the output map to move it, click to pin it, or click a data point to use that example. The Neuron tab shows its arithmetic.', touch: 'One input is always being traced through the network: the probe. Drag on the output map to move it, or tap a data point to use that example. The Neuron tab shows its arithmetic.' }] },
      { title: 'Hidden space and the loss landscape', paras: ['Hidden space shows how each layer rearranges the data, layer after layer, until the classes come apart. The loss landscape maps the loss around the current weights along the two directions training moved in most, with the path it took across that map.'] },
      { title: 'The explanations', paras: ['Insights says what is going on and suggests experiments, some of which ask you to predict the result first. Neuron and Layer give the numbers of what is selected, Training the loss curves, and Backprop one training step worked through. On a phone they are the Inspect screen.'] },
      { title: 'History', paras: ['The timeline under the diagram keeps the training history: step back through it (← and → with the timeline focused), and Train from here goes on from an earlier step.'] },
      { title: 'Changing the network', paras: ['− and + under a layer change its size; the + between layers, or the Hidden layers control, add depth; the chip under each layer picks its activation function, and a selected neuron can have its own. The maps and the numbers follow at once.'] },
    ] },
    { id: 'models', title: 'The models', generated: 'models' },
    { id: 'labs', title: 'The labs', sections: () => [
      { title: 'Model Builder', paras: ['Build a model from parts and train it: drag parts between the Input and the Output (or ' + tap(true) + ' them), drag blocks to reorder them, and drag one off to remove it. There are dense layers and neurons, convolutions and pooling, attention, recurrent cells (RNN, LSTM, GRU), normalization and dropout, gated layers (GLU, SwiGLU, GEGLU), and parallel branches joined side by side or by adding, multiplying or averaging. A few blocks can be boxed into a part of your own and reused, like a function.',
        'Each part has its own guide, with a small moving picture of what it does. What is happening explains a run in plain words, challenges set a goal to reach, classic models (trees, boosting and others) train on the same data for comparison, runs can be compared side by side, and the Python tab writes the whole script in PyTorch: press Edit (or double-click a line) to change it, and Apply reads your changes back into the model, or says which line it could not follow and puts the script back. Its Architecture view draws your model as a network or as boxes, and Growth films each run with the math of its steps.',
        `Learn from rewards has problems with no examples at all: 18 worlds from beginner to expert, from levers that pay when they match a light, a room to keep warm and hurdles to jump, through a pole to balance, a lamp to remember and a cart to rock out of a valley, to a race track, a deceptive maze, a rocket to land and sheep to herd (the Reinforcement learning chapter has them all). Each can be seen more than one way (a few numbers, a picture for convolutions, or the last few readings for a recurrent layer), and the network you build learns by ${rlMethods()}, chosen in the Training tab with the rest of how it learns. With grow and prune on, evolution reshapes the network itself a neuron at a time; and on problems with answers, the Training tab can grow and prune a network while it learns. Its inputs and Its reward change the world itself: leave inputs out or add sensor noise, set what each event pays or write the reward as a formula of your own, and change each world’s own settings, from the pole’s length and gravity to the weather outside the room. The results play it live with its outputs beside the world, the score is how its best moves do at the real goal, What is happening says what they get stuck on, and the Python tab writes the world and the method’s whole loop.`],
      acts: [open('builder'), ['Its Architecture view', () => arch('builder')], ['Its Growth view', () => growth('builder')], ['Balance a pole', () => lab('builder', (L) => L.setProblem('pole'))], ['Race a car', () => lab('builder', (L) => L.setProblem('track'))]] },
      { title: 'Tiny Transformer', paras: ['A small language model that runs in your browser. Type a prompt and follow it through the token embeddings, the attention layers and the MLP blocks, to the probability of each next token. The Tokens view shows every token through every stage; the embedding views map tokens, output vectors and positions; the Architecture view opens every part, down to one attention head and what each position looks at. Growth films it learning again from scratch: grammar within seconds, lookups after about 2,000 steps.'],
        acts: [open('transformer'), ['Its Architecture view', () => arch('transformer')], ['Its Growth view', () => growth('transformer')]] },
      { title: 'Physics-Informed Network', paras: ['Ten noisy measurements of a damped spring, all from its first third of a second: a plain network fits them and has no idea what happens next. The physics-informed network is also trained on how far its curve is from obeying the spring’s equation at 40 points in between, using the network’s own exact derivatives, so it carries on correctly where there is no data. The Plots view shows the fits, the residual and the phase portrait; the Architecture view opens the network and its loss; Growth films both networks learning, with the PINN’s loss written out term by term.'],
        acts: [open('pinn'), ['Its Architecture view', () => arch('pinn')], ['Its Growth view', () => growth('pinn')]] },
      { title: 'Diffusion Model', paras: ['It makes new data by learning to remove noise. Add noise shows the forward process that buries the data in noise; Denoiser shows where the network thinks each noisy point came from; Generate turns pure noise into new points step by step, with DDPM (random) or DDIM (deterministic) sampling. Growth films noise learning to become the data.'],
        acts: [open('diffusion'), ['Its Architecture view', () => arch('diffusion')], ['Its Growth view', () => growth('diffusion')]] },
      { title: 'YOLO26 Object Detector', paras: [{ mouse: 'It finds every object in a scene in one pass. In Detect, drag a shape to move it, scroll on it to resize it and double-click to remove or add one: the boxes follow, computed in your browser. Compare heads puts the one-to-one head (no NMS needed) beside the one-to-many head with NMS; Grids shows the three scales it predicts at; Architecture opens the whole detector; Growth plays its training log, epoch by epoch, with its loss and the MuSGD optimiser written out.', touch: 'It finds every object in a scene in one pass. In Detect, drag a shape to move it, pinch to resize it and twist to turn it, and double-tap to remove or add one: the boxes follow, computed on your phone. Compare heads puts the one-to-one head (no NMS needed) beside the one-to-many head with NMS; Grids shows the three scales it predicts at; Architecture opens the whole detector; Growth plays its training log, epoch by epoch, with its loss and the MuSGD optimiser written out.' }],
        acts: [open('yolo26'), ['Its Architecture view', () => arch('yolo26')], ['Its Growth view', () => growth('yolo26')]] },
      { title: 'Radar Pulse Classifier', paras: ['A convolutional network that names a radar waveform from its raw I/Q samples. Signal shows the samples, Spectrogram how the frequency changes over time, What the CNN sees the network’s feature maps, and Accuracy how well it does at each signal-to-noise ratio, from −12 to +20 dB. Growth plays its training log: clean signals are learned first, noisy ones last.'],
        acts: [open('radar'), ['Its Architecture view', () => arch('radar')], ['Its Growth view', () => growth('radar')]] },
      { title: 'Reinforcement learning', paras: ['Five examples where an agent learns from rewards alone: a maze with a table, mazes with a network, two board games learned by playing itself, and a network bred by evolution to balance a pole. The next chapter but one has them in full.'], acts: [open('rl-maze'), open('rl-mazes'), open('rl-evolve')] },
    ] },
    { id: 'down', title: 'All the way down', sections: () => [
      { title: 'Zoom views', paras: [`Every model has a zoom view: the labs’ Architecture view, and in the network models any neuron (zoom far into it, or ${touch() ? 'tap' : 'double-click'} it). Each level fills the screen and is computed from the live model, so the numbers inside are the real ones for the current input. ${NA.openHint ? NA.openHint('a part', { cap: true }) : ''}.`],
        acts: [['Open a neuron', () => neuron('spiral', 1, 0)]] },
      { title: 'From a model to the electrons', paras: ['The levels go: the model and its blocks; a layer; one neuron; its weighted sum and the PyTorch line that computes it; what that library call does inside; one floating-point multiplication or addition, bit by bit (sign, exponent and mantissa); the partial products and the adders that sum them; full adders; logic gates; the transistors of a gate (CMOS); and the electrons moving through a transistor’s channel. In the Architecture views every heatmap cell and bar opens the same way.'] },
      { title: 'Where numbers live', paras: ['Any stored number opens into its bits, and a bit into the memory cell that holds it: in DRAM, one transistor and one capacitor, read through a word line, a bit line and a sense amplifier. Each number says whether it is an input, a learned weight or an activation, and so how long it has to stay in memory.'] },
      { title: 'Merge', paras: ['Merge keeps the level of detail you were at when you zoom back out. The parts around it are drawn the same way, side by side, each framed and named: stored numbers join into one memory array with its word lines and bit lines, gates and transistors appear inside their circuit’s own picture, and the full adders of an adder line up as a carry chain.'] },
      { title: 'Linked words', paras: [{ mouse: 'In the explanations, words that name a part of the picture are linked to it: point at the words and the part lights up; point at the part and its words light up.', touch: 'In the explanations, words that name a part of the picture are linked to it: tap the words and the part lights up.' }] },
      { title: 'Follow a weight', paras: ['At a neuron’s weighted sum, Follow a weight ▶ takes one learned weight on a guided walk: down through the multiplication to the transistors that compute it, and back up to the loss, one level at a time.'], acts: [['Open a neuron', () => neuron('spiral', 1, 0)]] },
      { title: 'Flip bits and number formats', paras: [`At a stored weight, turn on Flip bits and ${tap(true)} any bit to flip it: the network changes at once, and a flipped exponent bit can wreck it (↶ Undo puts it back). The format menu stores every weight as bfloat16, FP16 or FP8 (E4M3) instead of float32, to see how much precision a network really needs; float32 brings the originals back exactly.`] },
      { title: 'The adder’s clock', paras: ['At an adder, ⏱ Step the clock runs an addition one gate delay at a time: the carry ripples along, and the counts show how many gates and transistors it takes.'] },
      { title: 'Build your own full adder', paras: ['At a full adder, Build your own opens a board where you wire logic gates from A, B and carry-in to the sum and carry-out, with a truth table that checks all 8 cases as you go. Put it to work and every adder in the zoom views is made of your circuit, right or wrong: a mistake shows up in the multiplications and in the neurons above them.'] },
      { title: 'Zooming out past the network', paras: ['Zoom out below the network’s smallest size and the view keeps going: your network shrinks to a dot beside the models of this site’s labs, all of them fit in a corner of the smallest GPT-2, and GPT-2 in a corner of one GPU’s memory. Each square has the area of its number of weights.'], acts: [['Zoom out past the network', () => scale()]] },
      { title: 'Code at every level', paras: ['The Python tab beside each explanation shows that level as code: the PyTorch line of a neuron, a library routine written out, a float multiplication in plain Python, a full adder as logic. In a lab it starts with the whole model.'] },
    ] },
    { id: 'rl', title: 'Reinforcement learning', sections: () => [
      { title: 'Learning from rewards', paras: ['No examples of good play: the agent only gets rewards (reaching a goal, winning a game) and has to find out what earns them. Its Architecture view draws it as a loop: what it sees, its model, its choice, the answer of the maze or the game, and how it learns from that. Each box opens; the model opens into its layers and neurons, down to the transistors.'],
        acts: [['The agent’s loop', () => arch('rl-mazes')]] },
      { title: 'Maze Runner: Q-learning', paras: ['A Q-table holds one number for each square and move: the reward it expects if it makes that move there and then plays its best. After every move, that entry moves toward the reward it got plus γ times the best value of where it landed, so values spread back from the goal until the arrows show a route. ε sets how often it explores at random, α how far each update moves, γ how much later rewards count. On a slippery floor it learns to keep away from the pits. It learns this maze, not mazes: Train on can give it a new random maze every episode, and a table learns nothing from that, since its rows are squares, not situations.'],
        acts: [open('rl-maze'), ['Watch it learn', () => lab('rl-maze', (L) => L.runTry({ action: 'watch' }))]] },
      { title: 'Many Mazes: a Q-network', paras: ['A table fits one maze: its rows are that maze’s squares. The Q-network is not told its square at all. It sees the 24 squares around it (walls, pits, the goal, where it has been) and which way the goal lies, so the same weights work in any maze. Every training episode is a new random maze, easy ones first (while it trains, the board shows them), with a replay memory and a target network as DQN did on Atari games. It never trained on the five named mazes and gets through all of them, and through most random mazes nobody has seen. Switch Train on to the maze shown only and it overfits: it keeps that maze and loses the rest.'],
        acts: [open('rl-mazes'), ['A maze nobody has seen', () => lab('rl-mazes', (L) => L.newMaze())]] },
      { title: 'Three-line and Four-line: self-play', paras: ['Board games made for this site: three in a row on a 4 × 4 board, and four in a row on 5 × 5. The agent plays both sides and learns by temporal differences: after each move, the value of its previous position moves toward the value of the next one, and at the end toward the result. Three-line can keep a table of the positions it has met or use a small network, which learns faster since what it learns about one position carries over to similar ones; Four-line has far too many positions for a table.'],
        acts: [open('rl-three'), open('rl-four')] },
      { title: 'Testing it slowly', paras: [`Test run (in a maze) and Watch it play (in a game, against a rule-follower that wins when it can and blocks when it must) play its best moves back one step at a time: pause, step back and forth (or use the arrow keys), and change the speed. Beside the board, Inside its model shows what the model computes at that step: what it sees, which hidden neurons fire, and what comes out. In a game, ${touch() ? 'touching' : 'pointing at'} an empty cell shows the network on that move.`],
        acts: [['Test run on a maze', () => lab('rl-mazes', (L) => L.startTest())], ['Watch Four-line play', () => lab('rl-four', (L) => L.startTest())]] },
      { title: 'Playing against it', paras: [`Play blue (first) or Play orange (second) above the board, or ${tap(true)} an empty cell to start as blue. It always plays its best move by what it has learned so far: train it more, and it gets harder to beat.`],
        acts: [['Play Four-line', () => lab('rl-four', (L) => L.startPlay(1))]] },
      { title: 'Evolution: a genetic algorithm', paras: ['No gradients and no reward for any single move: a population of 30 small networks (4 inputs, 8 tanh neurons, 2 outputs: push the cart left or right) takes turns balancing a pole, and each one’s fitness is how long the pole stayed up. The best two carry on unchanged; every other place goes to a child of two fit parents, with each weight from one or the other and a few mutated. The bars under the cart are the last generation, fittest first; the Training tab follows the best, the average and the worst.',
        `Try it yourself balances the pole with your own hands: hold ← or → (or press either half of the board), then see how long the network lasts from the same start. The experiments switch off mutation or the elite, or shrink the population, to see what each part of the algorithm does.`],
        acts: [open('rl-evolve'), ['Watch it evolve', () => lab('rl-evolve', (L) => L.runTry({ action: 'watch' }))], ['Try it yourself', () => lab('rl-evolve', (L) => L.startPlay())]] },
      { title: 'In the model builder', paras: [`Learn from rewards puts the same ideas in your hands: build any network, pick one of 18 worlds, how it sees it, and how it learns: ${rlMethods()}. The worlds go from beginner to expert, and the next sections take them level by level. Its challenges are about rewards themselves: exploring, a bonus for getting closer, looking further ahead, memory, a learning rate that is too large, finding the way through mazes it has never seen, getting round a track, a slope for evolution to climb, and a network that grows its own layers; and in the newer worlds, rewards that pay for the wrong thing (a thermostat paid for warmth, a runner charged for every step, an arm paid by the hour), seeing what matters (the next hurdle, the traffic), a lamp it has to remember, and a maze whose reward leads into a wall.`,
        'Evolution in the builder shows a whole generation at once: every car of a generation driving the track from the same start, coloured as their bars, or every rocket coming down together. Its settings are in the Training tab, with every other method’s: how parents are chosen (a tournament, the top fifth, by rank), how they are mixed (weight by weight, neuron by neuron, or not at all), and plain or safe mutations. Grow and prune lets a child change its shape a neuron at a time, with a size penalty so that it grows only when growing pays (Grow and prune, below, has the details). MAP-Elites keeps the best network of each of 144 styles of play; a click on a cell of its grid watches that style play. Jump in, above the picture, hands you the controls of the episode where it is (the arrow keys, or buttons to hold on a touch screen), with the trained network’s outputs beside each of your moves; Let it play hands them back, and the network carries on from where you left it. The button at the top right of the results puts the picture full screen (Esc puts it back), and there a key of the world’s jumps in at once.',
        'You set the world too. Its inputs, in the Input block’s panel: leave some out (the pole’s speeds, the ball’s drift, the radiator’s temperature), add extra ones (its last move, the time left, a hint) or sensor noise, and see whether the network can do without. Its reward, in the Reward tab (the line under the results’ title opens it): what each event pays (the goal, a pit, every step, a fall), or a formula of your own over the world’s numbers, such as 1 − abs(angle)/12 for the pole; Write the table as a formula turns the amounts into one to start from. The agent only ever collects reward, so the reward is the goal it is given; the score keeps measuring the real goal, and a reward that pays for something else shows there (What is happening says so when its return climbs and its score does not: reward hacking). Learning from rewards can also get worse again after it has played well, so a run that ends below its best score ends with the network it had at its best (Keep the best network, in the Training tab). The world itself: the pole’s length, push and gravity (Moon to Jupiter), the levers’ odds, the longest episode, the ball’s drift, the weather and insulation of the room, the number of sheep, and more.'],
        acts: [['Learn from rewards', () => lab('builder', (L) => L.setProblem('rlmaze'))]] },
      { title: 'Looking closer, guessing first, and paths', paras: ['The Analyse tab looks closer at the run on show. Sweep a setting trains a fresh copy briefly at several values of one setting (batch size, weight decay, the optimizer, a layer’s width) from the same start, and compares them. Luck trains the same setup from 3 or 5 seeds, one run after another, and says how far their scores spread: a change that moves the score by less may be luck.',
        'For a trained classifier: how sure it is against how often it is right (calibration, with the temperature that would make it honest), which inputs it leans on (each shuffled in turn: permutation importance), and, for pictures, how a nudge of ε to every pixel in the worst direction (FGSM) can change its answer. For any network: how much of its score survives pruning its smallest weights or rounding them to a few bits, and how small that makes it.',
        'Guess first, in the Runs tab: turned on, each new run first asks what score you expect, and its end says how close you were. Paths, at the top of the Challenges, lead through the challenges in an order that builds one idea on another.',
        'Three more parts: a Skip connection adds (or joins) the output of any earlier block, as ResNets and U-Nets do; a Kolmogorov–Arnold layer learns a curve on every edge instead of a number; a Hopfield memory recalls the learned pattern most like its input. And More than one right answer, where a mixture of bell curves finds every branch that squared error averages away.'],
        acts: [['More than one right answer', () => lab('builder', (L) => L.setProblem('branches'))], ['Skip connections', () => lab('builder', (L) => { L.setProblem('spiral'); const t = NA.builderTasks.TEMPLATES.find((q) => q.id === 'skips'); if (t) L.applyTemplate(t); })]] },
      { title: 'Making, rebuilding and labelling: six more kinds of problem', paras: ['Squeeze and rebuild: an autoencoder narrows each picture to a short code and rebuilds it from that alone. With 2 numbers in the middle the codes make a map where similar pictures lie together, though no label was ever given. A VAE’s middle is a bell curve (the Sample part), pulled toward one standard bell curve, so codes drawn from that curve decode to new pictures. Cleaning up noisy pictures is the same with damaged pictures in.',
        'Make new examples, a GAN: your model is the generator, turning random numbers into points or pictures; a second network, the discriminator, learns to tell them from real ones, and the generator learns to fool it. Behind the points, where the discriminator thinks points real, and a line from each generated point the way it is pushed. Its score is precision (they look real) and recall (they cover all the real ones): a generator that finds only some of the blobs has collapsed.',
        'Learn without labels: each picture is shown as two random views, and the model learns codes that put the two together and other pictures apart (contrastive learning, the NT-Xent loss of SimCLR). The labels are used only to score it: a vote of the nearest codes, beside the same vote on the raw pixels.',
        'Label every pixel: segmentation gives every pixel a class. A tiny U-Net pools the picture down to see whole shapes, upsamples it back (the Upsample part) and joins it with the picture as it was, a skip connection, so its answers keep their edges. It is scored by the overlap of its shapes with the true ones.',
        'Graphs: each node is classified from its own features and its neighbours’. The Graph convolution part averages (or adds up) a node’s and its neighbours’ features before a dense layer; two of them let a node hear its neighbours’ neighbours. Without message passing the groups cannot be told apart.',
        'Predict with uncertainty: two outputs, a middle and the log of a spread squared, trained with the Gaussian loss, give a band that widens where the data is noisier, and the share of points inside it says whether the spread is right. The spread is the noise it saw, not what it does not know: across a gap in the data it can be wrong and sure at once.'],
        acts: [['A VAE', () => lab('builder', (L) => L.setProblem('vae'))], ['A GAN', () => lab('builder', (L) => L.setProblem('ganring'))], ['A tiny U-Net', () => lab('builder', (L) => L.setProblem('segment'))], ['Friend groups', () => lab('builder', (L) => L.setProblem('groups'))]] },
      { title: 'NEAT, families of shapes, populations', paras: ['NEAT grows networks of its own: every member starts with no hidden neuron, and mutations add connections and neurons. Members are grouped into species by how different their genes are and share their fitness within their species, so a new structure has room to improve. Beside the results: the network it grew (blue and red by the sign of each weight) and its species over time.',
        'With grow and prune, the genetic algorithm keeps a family tree of shapes: every shape its networks have had, placed at the generation it appeared, linked to the shape it came from, bigger when more members had it.',
        'Population-based training, in the Training tab: 4 or 8 learners side by side, each from its own seed with a learning rate of its own; every 500 steps the worst quarter copy the best quarter and nudge their learning rates. It searches for a good learning rate while it learns, at the cost of training several.'],
        acts: [['NEAT on the pole', () => lab('builder', (L) => { L.setProblem('pole'); L.setMethod('neat'); })]] },
      { title: 'Looking closer at a learner', paras: ['Its score comes from a few episodes. Test it 100 times, in the Training tab, plays 100 more, each from a start it has not been scored on, and counts how they ended (reached the goal, fell in a pit, ran out of steps), with its returns and how long its episodes last: how sure the score is, and what goes wrong when it fails.',
        'Two more views beside the results. The value map: over two of its inputs (you choose which, the others as they are now), the value it expects at each place, DQN’s best Q-value or the critic’s, or the move it would make there; the ring is where it is now, and the map shifts as it plays. Where it went: every place its moves took it while it learned, brighter where it went more often, over the maze, the race track or the herding field: how it explored, and where it never went.'],
        acts: [['The value map on the pole', () => lab('builder', (L) => { L.setProblem('pole'); L.evoView = 'map'; })]] },
      { title: 'The knobs of PPO and DQN', paras: ['PPO’s steps, in the Training tab: the clip (how far a move’s probability may move from the policy that played it before the push stops), how many passes it makes over each batch, GAE λ (how far ahead its advantages look: 1 the whole return, lower the critic’s guesses sooner: less noise, more bias) and the entropy bonus (a little reward for keeping its choices open).',
        'DQN’s memory and targets: how many past moves it keeps, how often its target network is refreshed, double DQN (the network picks the next move, the target network values it), dueling (one output is the value of the state, the others each move’s advantage over the rest) and looking ahead (n-step returns: its next n rewards, then the value of where they led). Each is in the Python too.'],
        acts: [['DQN on the pole', () => lab('builder', (L) => { L.setProblem('pole'); L.setMethod('dqn'); })]] },
      { title: 'Easy first, dreams and rivals', paras: ['Easy first (a curriculum): the pole with weaker gravity, the arm’s target near its hand, the rocket starting low and slow, hurdles only early in the course. Each time 3 in 4 of its recent episodes succeed, the world gets a quarter harder, up to full difficulty; its score is always measured at full difficulty.',
        'A model of the world: a small network of its own learns, from every move, what comes next and what it will be paid. The Training tab then plays its best moves twice from one start, in the world and in the model’s imagination, each move fed what the model predicted: watch the dream drift from the world as small errors compound. Planning methods (Dyna, World Models, MuZero) practise in such dreams.',
        'Predator and prey: in Escape the chaser, the first chaser can learn too, a DQN of its own paid for catching the runner. Each learns against the other as it is now, an arms race like self-play, while the score is still measured against the chaser that follows its rule.'],
        acts: [['Escape a chaser that learns', () => lab('builder', (L) => { L.setProblem('chase'); L.setMethod('ppo'); L.edit((S) => { S.ps.chase.chaserLearns = true; }); })]] },
      { title: 'Controls that are numbers', paras: ['Four worlds can be controlled by numbers as well as moves: the robot arm (how hard each motor pushes, both at once, and the brake), the rocket (the main engine’s throttle, and turning), the walker (each muscle’s length) and the race track (steering, and the throttle, below 0 the brake). Three methods set numbers: choose one in Learns by and the world takes them; Jump in still plays with moves.',
        'PPO with a Gaussian policy draws each number from a bell curve whose middle the network gives. SAC draws from a curve too, and keeps it as wide as it can while two critics of their own, learning from a replay memory, say which tries are worth more. TD3 makes one try per state and adds noise to explore, trusts the smaller of its two critics, and learns every second step. SAC and TD3 learn from every move they keep, so they need far fewer moves than PPO, though each move costs more. The bars beside the picture show each number it sets, from −1 to 1, and its spread.'],
        acts: [['SAC on the robot arm', () => lab('builder', (L) => { L.setProblem('arm'); L.setMethod('sac'); })], ['PPO with numbers on the arm', () => lab('builder', (L) => { L.setProblem('arm'); L.setMethod('gauss'); })]] },
      { title: 'My models, and training in the background', paras: ['The Runs tab keeps networks for you: Keep this network puts the run’s setup and its trained weights on a shelf in this browser, under a name of yours. Open puts the setup back in the builder (Undo away) and the weights into a new run that starts where they were, so you can watch it play, look inside it, or train it further. Download saves one as a file, and Load a model file brings it back, in this browser or another. The latest run you paused or finished is kept there by itself, so a reload loses nothing.',
        'A tab you are not looking at gets no frames from the browser, so training would stop there. With Keep training (in the Training tab, When the page is hidden), a timer of its own trains it on, a little more slowly, and the tab’s title says how far it has got.'],
        acts: [['My models', () => lab('builder', (L) => { if (NA.mobile && NA.mobile.mobile) NA.mobile.go('insp'); L.tabs.select('runs'); })]] },
      { title: 'Worlds of your own', paras: ['Four worlds can be laid out by hand, in an editor that opens over the page from the world’s settings in the Input block. The maze: paint walls, pits and floor on its 8 × 6 squares and put the start and the goal anywhere. The race track: drag the points its middle line runs through, tap the grass for another. Hurdles: put each hurdle and bar where you like on the course. Herding: place the sheep and the dog where every game starts.',
        'The editor checks as you go and says what is wrong: a maze with no safe way to the goal, a bend too tight for the car, a track that runs into itself, two obstacles on top of each other, a sheep in the pen. Use this puts it in the settings, so Undo takes it back, a share link carries it, the run list says you made it, and the Python writes it out. Beside it is what the world pays, from the Reward tab: a layout and its rewards together make the problem.'],
        acts: [['Draw your own maze', () => lab('builder', (L) => { L.setProblem('rlmaze'); if (NA.worldEdit) NA.worldEdit.open(L, 'maze'); })], ['Shape your own track', () => lab('builder', (L) => { L.setProblem('track'); if (NA.worldEdit) NA.worldEdit.open(L, 'track'); })]] },
      { title: 'Reward worlds for beginners', paras: ['The builder’s 18 worlds to learn from rewards come in four levels, and each starts with the method that learns it best. In a beginner world the reward comes soon after the move that earned it, so a learner has something to go on from the start.',
        'Levers: a light shows a colour, and the lever of that colour usually pays; one pull an episode, the simplest problem where the best move depends on what it sees. Catch: move a paddle under a falling, drifting ball. Maze: find the goal and keep out of the pits, in one maze or a new one every episode. Keep a room warm: switch the heating on and off to keep a room within 1 °C of the temperature wanted, all day. The radiator is slow to warm up and slow to cool down, so a good thermostat switches off before the room is warm enough. Hurdles: a runner at 8 m/s has to take off between about 1 and 5 m before each hurdle to clear it, and on the mixed course duck under bars too.',
        'Beside the results, What is happening plays the network’s best moves again and says what they get stuck on, with the numbers: a room that overshoots, take-offs too early or too late, a lamp it cannot remember, a cart that never reaches the flag, a runner caught in a corner. Where a setting helps, its button is there.'],
        acts: [world('Keep a room warm', 'thermo'), world('Hurdles', 'hurdles'), world('Catch', 'catch')] },
      { title: 'Intermediate reward worlds', paras: ['Here the reward comes late or rarely, or what matters cannot be seen. Balance a pole: the classic control problem, seen as 4 numbers or as the last 4 readings. Remember the lamp: a lamp at the start of a corridor says which way to turn at its end, then goes dark (Memory, below). Mountain cart: an engine too weak to climb out of a valley, so it has to rock; every step costs 1 until the flag, so a cart that never gets there has nothing to learn from (Reward shaping, below). Swing up a pendulum: a motor too weak to lift it, so it swings it higher and higher, then catches it upside down and balances it there. Robot arm: two joints that keep turning once pushed, so it has to brake before its hand reaches the target. Traffic lights: keep or switch, for the cars queueing at a crossroads; every switch costs 4 steps of amber, and the rush hour moves from one road to the other. Walker: a creature of bones, springs and two muscles has to find a rhythm that walks it 10 m without toppling over; a clock among its inputs keeps time.'],
        acts: [world('Remember the lamp', 'memory'), world('Mountain cart', 'mountain'), world('Swing up a pendulum', 'swingup'), world('Traffic lights', 'traffic'), world('Walker', 'walker')] },
      { title: 'Advanced and expert reward worlds', paras: ['Race track: 4 laps, braking for the tight bends. Drone arena: a first-person view; turn, walk and fire before the drones reach it. Deceptive maze: the goal is behind a wall, and the reward for getting closer leads straight into it (Deceptive rewards, below).',
        'Land a rocket: the main engine and the side thrusters, softly onto the pad before the fuel runs out. Escape the chaser: the chaser is slower but heads straight for it, so running away works only until a wall stops it, and it has to learn to circle round; set the chaser to head for where it is going instead, and it is far harder to shake off. Herd the sheep: sheep keep together and run from the dog, so it has to get behind them, on the side away from the gate, and push, stragglers too.'],
        acts: [world('Deceptive maze', 'trap'), world('Escape the chaser', 'chase'), world('Herd the sheep', 'herd')] },
      { title: 'Reward shaping', paras: ['A reward that comes only at the end (the maze’s goal, the flag, the target) teaches nothing until something stumbles on it. Shaping adds small rewards on the way that say which way is warmer. The maze’s closer bonus pays 0.1 for each step nearer the goal by the shortest safe way, and takes as much off for each step away. The mountain cart’s energy bonus (off at first: it is in Its reward) pays for every gain in height plus speed, so rocking backwards to build up speed pays too. The robot arm’s approach reward pays, every step, for how much nearer the target its hand came, and the herd for every metre the sheep come nearer the gate.',
        'Each of these pays the change in one number, a distance or an energy, so along any route its payments add up to how much better the end is than the start. The goal itself still pays the most, so shaping of this kind cannot change which behaviour is best (Ng, Harada and Russell, 1999); what it changes is how soon a learner finds out. In our runs, without it actor-critic brought the arm’s hand to none of its targets (with it, 9 of 10) and evolution penned no sheep (with it, all 3 at its best); with the energy bonus DQN got the cart to the flag from all 10 starts in 5 runs of 5, and without it never. A guide can mislead too: Deceptive rewards, next.'],
        acts: [world('Mountain cart', 'mountain'), world('Robot arm', 'arm')] },
      { title: 'Deceptive rewards and novelty search', paras: ['In the deceptive maze the goal sits just above a wall, and the way round starts by heading away from it, to the far end. Paid for every step closer in a straight line, a learner heads straight for the goal and ends pressed against that wall, where every move looks worse: the reward itself holds it there. In our runs PPO, DQN and actor-critic ended there every time (13 runs between them), as did the cross-entropy method and evolutionary RL, and a genetic algorithm in 4 runs of 5.',
        'MAP-Elites keeps the best network for every place a run ends (its grid of styles is where the robot finishes), so it keeps the ones that went the long way round though they scored no better, and breeds from them: it reached the goal from all 3 starts in 8 runs of 10. Novelty search (Lehman and Stanley, 2011), the maze’s own method, ignores the reward altogether and breeds the networks that end up where none has ended before. The population spreads into every corner of the maze, the far end and the way round included, and it found the goal from all 3 starts in 5 runs of 5. Mixed half and half with the reward, it did in only 2 of 5: the reward pulls it back to the wall. A deceptive reward is the dark side of shaping: a guide that points at the goal straight through a wall.'],
        acts: [world('Deceptive maze', 'trap')] },
      { title: 'Memory: what it cannot see now', paras: ['Some worlds hide what matters. In Remember the lamp, the lamp says which way to turn at the end of the corridor, then goes dark. Seeing only the present (Only now), the robot reaches the junction with nothing to go on: whatever it learns, it turns the right way in half the corridors, by every method. Last 16 readings gives it its recent past, the lamp among it. Dense layers read it through a Flatten, a GRU in order, oldest first; either way it turned the right way in every corridor in our runs (PPO, DQN and a genetic algorithm with a Flatten, PPO with a GRU).',
        'The pole’s Last 4 readings view works the same way: positions and angles alone say nothing about speed, but how they change from reading to reading does. A Sequence pool that keeps only the latest reading throws that away again.'],
        acts: [world('Remember the lamp', 'memory'), ['With the last 16 readings', () => lab('builder', (L) => { L.setProblem('memory'); L.setWorldView('history'); })]] },
      { title: 'Novelty search, the cross-entropy method and evolutionary RL', paras: ['Three more ways to evolve a network, beside the genetic algorithm, evolution strategies and MAP-Elites. Novelty search breeds like the genetic algorithm but picks its parents for being different: how far each one’s behaviour (two numbers the world measures, such as where it ended up) is from its 10 nearest neighbours, in the generation and in an archive that keeps 2 new behaviours from each generation. It never aims at the goal, so a dead end that looks like progress cannot trap it (Lehman and Stanley, 2011); the network on show is the best by score it has met on the way.',
        'The cross-entropy method keeps a bell curve over every weight, a middle and a spread. Each generation draws networks from it, and the best fifth set the next middle and spread, so the search narrows where good networks agree and stays wide where they do not. Evolutionary RL (ERL; Khadka and Tumer, 2018) runs a genetic algorithm and a DQN together: every move the population makes goes into the DQN’s replay memory, the DQN learns from them between generations, and every few generations its network joins the population, where it breeds if it plays well. Evolution explores and copes with rewards that come late; gradient steps make fine use of every move.'] },
      { title: 'Grow and prune, a neuron at a time', paras: ['With grow and prune on, a child of the genetic algorithm can change its shape as well as its weights, one small step at a time. Most often it gains or loses a neuron. A new neuron starts with outgoing weights of 0, so it changes nothing until later mutations put it to work; the neuron pruned is the one the next layer listens to least.',
        'A new hidden layer starts with a single neuron. Such a narrow layer is a bottleneck: it passes on only the signals the next layer leans on most, so unlike a new neuron it changes what the network does, and selection keeps it only if the child still plays well; later neurons widen it without changing anything. A layer goes only when its last neuron is pruned, folded into the next. A size penalty takes a little off the fitness for every 100 weights, so the network grows only where growing pays: the line under the results gives its shape now beside the one you built.',
        'Every part of it can be set in the Training tab: start from the network you built or from no hidden layer at all, as NEAT does; which changes it can make (a neuron more or less, a new layer, a whole layer out at once, a new activation) and whether it leans to grow or to prune, with the odds of each change worked out beside them; how many children change; whether a new layer starts with one neuron, a few or a whole layer, passing values on or at random, and where it goes; whether a new neuron starts silent or at random; whether pruning takes the weakest neuron or one at random; the largest network; the size penalty; and protection for new shapes: a new shape usually starts a little worse, so for 5 generations its best member carries on unchanged and mutations get time to tune it, a simple form of NEAT’s speciation. The whole generation’s view counts its shapes, and the Python writes every one of these choices.'],
        acts: [['Grow a network on the pole', () => lab('builder', (L) => { L.setProblem('pole'); L.useMethod({ world: 'pole', method: 'ga', grow: true, label: 'Grow and prune' }); })], ['Grow one from nothing', () => lab('builder', (L) => { L.setProblem('pole'); L.useMethod({ world: 'pole', method: 'ga', grow: true, label: 'Grow and prune' }); L.edit((S) => { S.ps.pole.growStart = 'small'; }); })]] },
      { title: 'Watching it play, racing and recording', paras: ['The picture beside the results plays the network’s best moves, one episode after another. The bar under it pauses and plays (K), steps one move back or on, slides through the episode so far, and plays at a quarter of the speed up to four times; New episode starts another. The corner button fills the screen with the picture, the same bar under it, and Jump in works there too.',
        'Race… plays two side by side, from the same start every episode: two of your runs (the networks they ended with), or you against a run, your keys driving one side. The one whose episode returns more wins it, and the wins are counted, so one lucky start decides nothing.',
        'Record a video starts a new episode and records the picture until it ends, then saves it as a video file (WebM, or MP4 where the browser makes only those), to keep or to share.'],
        acts: [world('Balance a pole', 'pole'), world('Race track', 'track')] },
      { title: 'Teaching it yourself', paras: ['Two ways to learn from you rather than from a reward table, in Learns by and among the parts. Copy you (behaviour cloning) learns from your play: Jump in and play an episode or two, then train, and it learns your move in every moment you played as a classifier learns its classes. It copies your moves, not your results: one move unlike yours takes it into a moment you never showed it, so show it more there, or let rewards take it further.',
        'Which did better? (learning from preferences) shows you two tries from the same start side by side and asks which did better (← for the first, → for the second, ↓ when they did as well). A second network, the reward model, learns a reward for every move whose totals agree with your answers, and PPO learns from that reward: the idea behind RLHF, how chatbots learn which answers people prefer. Or let the world’s own reward answer, five times as often, and watch how far its answers and yours agree.',
        'Start from, in the Training tab, begins a run from another run’s network rather than new random weights: a copy of your play handed to PPO, or a network trained on one world carried on with another method. It needs the same inputs and outputs, and says which runs fit.'],
        acts: [['Copy you on the pole', () => lab('builder', (L) => { L.setProblem('pole'); L.setMethod('bc'); })], ['Which did better? on the pole', () => lab('builder', (L) => { L.setProblem('pole'); L.setMethod('pref'); })]] },
      { title: 'Finding a setting', paras: ['How it learns is set in one place, the Training tab: the method and its every setting, the rewards, grow and prune, Start from. The panels of the blocks say what the block does and open the Training tab at the right place where a setting lives there.',
        'Find a setting (/) searches every setting of the builder by name or by what it does, “learning rate”, “how often it explores”, “bigger network”, and opens the panel where it is, the setting lit up. It finds the settings of the problem and the method in use, and the things that are not settings too (full screen, Record a video, Race, editing the Python); when nothing matches, it offers to search the Guide.'],
        acts: [['Find a setting', () => lab('builder', (L) => { if (NA.mobile && NA.mobile.mobile) NA.mobile.go('insp'); if (L.finder) L.finder.focusInput(); })]] },
    ] },
    { id: 'keys', title: 'Keys and gestures', sections: () => [
      { title: 'Keyboard', keys: [['Space', 'Train or pause (in a test of the RL lab: play or pause it)'], ['S', 'One training step (in a test: one step on)'], ['R', 'Start again from new random weights'], ['T', 'Run the held-out test (in the RL lab: a test run)'], ['1  2  3', 'Connections: weight, signal, gradient'], ['4  5  6', 'Neurons: activation, pre-activation, gradient'], ['M  V  B  F  A  H', 'Maps, values, bias, flow, functions, health'], ['Enter', 'Open the selected part of a zoom view'], ['Esc  ·  Backspace', 'Back out one level'], ['←  →', 'Step through the history (with the timeline focused), or through a test'], ['Ctrl Z  ·  Ctrl Y', 'Undo and redo in the model builder (Delete removes the selected block)'], ['/', 'Find a setting in the model builder'], ['K', 'Pause or play the picture of a world that learns from rewards'], ['←  ↓  →', 'Which did better?: the first, as well, the second'], ['?', 'How to read the network, and these keys']] },
      { title: 'Mouse', keys: [['Point', 'What a neuron or a part is, in a tooltip'], ['Click', 'Select it: the explanation shows it'], ['Double-click', 'Open it'], ['Wheel', 'Zoom; far enough in, the part under the pointer opens'], ['Drag', 'Pan']] },
      { title: 'Touch', keys: [['Tap', 'Open a neuron or a part of a zoom view (a part that does not open is shown instead)'], ['Hold', 'See what it is: the explanation opens'], ['Pinch', 'Zoom; far enough in, the part under your fingers opens'], ['Drag', 'Pan'], ['Double-tap', 'Zoom the network diagram in or out']] },
    ] },
    { id: 'terms', title: 'Glossary', generated: 'terms' },
  ];

  // the gallery and the glossary, from their own data
  function generated(kind) {
    if (kind === 'models') {
      const { PRESETS, GROUPS } = NA.presets;
      return GROUPS.flatMap((g) => PRESETS.filter((p) => p.group === g).map((p) => ({ title: p.name, kicker: g, paras: [p.tagline, p.about].filter(Boolean), meta: p.meta, acts: [['Open', () => load(p.id)]] })));
    }
    const T = (NA.glossary && NA.glossary.terms) || [];
    return T.slice().sort((a, b) => a.term.localeCompare(b.term)).map((t) => ({ title: t.term, paras: [t.def], term: true }));
  }
  const sectionsOf = (c) => (c.generated ? generated(c.generated) : c.sections());
  const textOf = (s) => [s.title, s.kicker, s.meta, ...(s.paras || []).map(say), ...(s.keys || []).flat()].filter(Boolean).join(' ').toLowerCase();

  // ------------------------------------------------------------------ the dialog
  function build() {
    G.search = el('input', { class: 'gd-search', type: 'search', placeholder: 'Search the guide', 'aria-label': 'Search the guide', spellcheck: 'false', autocomplete: 'off' });
    G.toc = el('nav', { class: 'gd-toc', 'aria-label': 'Chapters' });
    G.main = el('div', { class: 'gd-main', tabindex: '-1' });
    G.count = el('p', { class: 'gd-count', 'aria-live': 'polite' });
    G.closeBtn = el('button', { class: 'icon-btn', type: 'button', 'data-close': '', 'aria-label': 'Close the guide' }, '×');
    G.dlg = el('div', { class: 'modal gd-modal', id: 'guide', role: 'dialog', 'aria-modal': 'true', 'aria-labelledby': 'gdTitle', hidden: '' },
      el('div', { class: 'sheet gd-sheet' },
        el('div', { class: 'sheet-head gd-head' },
          el('div', null, el('h2', { class: 'sheet-title', id: 'gdTitle', text: 'Guide' }), el('p', { class: 'sheet-sub', text: 'Everything this site shows and explains, and how to use it.' })),
          G.closeBtn),
        el('div', { class: 'gd-find' }, G.search, G.count),
        el('div', { class: 'gd-body' }, G.toc, G.main)));
    G.dlg.addEventListener('click', (e) => { if (e.target === G.dlg || e.target.closest('[data-close]')) G.close(); });
    G.dlg.addEventListener('keydown', (e) => { if (e.key === 'Escape') { e.stopPropagation(); G.close(); } });
    G.search.addEventListener('input', () => render());
    // the chapter being read is lit in the list of chapters
    G.main.addEventListener('scroll', () => { if (!G.ticking) { G.ticking = true; requestAnimationFrame(() => { G.ticking = false; spy(); }); } }, { passive: true });
    document.body.append(G.dlg);
  }
  function render() {
    const q = G.search.value.trim().toLowerCase(), words = q.split(/\s+/).filter(Boolean);
    clear(G.toc); clear(G.main);
    let shown = 0;
    for (const c of CHAPTERS) {
      const secs = sectionsOf(c).filter((s) => !words.length || words.every((w) => textOf(s).includes(w)));
      if (!secs.length) continue;
      shown += secs.length;
      G.toc.append(el('button', { class: 'gd-tab', type: 'button', dataset: { ch: c.id }, onclick: () => jump(c.id) }, c.title, words.length ? el('span', { class: 'gd-n', text: String(secs.length) }) : null));
      const body = c.id === 'terms' ? el('dl', { class: 'gd-terms' }, ...secs.flatMap((s) => [el('dt', { text: s.title }), el('dd', { text: s.paras[0] })])) : el('div', { class: 'gd-secs' }, ...secs.map(section));
      G.main.append(el('section', { class: 'gd-ch', id: 'gd-' + c.id, dataset: { ch: c.id } }, el('h2', { class: 'gd-ch-title', text: c.title }), body));
    }
    if (!shown) G.main.append(el('p', { class: 'gd-none', text: 'Nothing in the guide matches. Try another word, or fewer.' }));
    G.count.textContent = words.length ? `${shown} ${shown === 1 ? 'section matches' : 'sections match'}` : '';
    spy();
  }
  function section(s) {
    return el('article', { class: 'gd-sec' },
      s.kicker ? el('p', { class: 'gd-kicker', text: s.kicker }) : null,
      el('h3', { class: 'gd-sec-title', text: s.title }),
      ...(s.paras || []).map((p) => el('p', { text: say(p) })),
      s.meta ? el('p', { class: 'gd-meta', text: s.meta }) : null,
      s.keys ? el('dl', { class: 'gd-keys' }, ...s.keys.flatMap(([k, v]) => [el('dt', null, ...k.split('  ').map((x) => el('kbd', { text: x.trim() }))), el('dd', { text: v })])) : null,
      s.acts && s.acts.length ? el('div', { class: 'gd-acts' }, ...s.acts.map(([label, fn]) => el('button', { class: 'btn', type: 'button', onclick: fn }, label))) : null);
  }
  function jump(id) {
    const t = G.main.querySelector(`[data-ch="${id}"]`);
    if (t) { G.main.scrollTop = t.offsetTop - G.main.offsetTop - 4; spy(id); }
  }
  function spy(force) {
    const chs = [...G.main.querySelectorAll('.gd-ch')], top = G.main.scrollTop + G.main.offsetTop + 40;
    let cur = force || (chs[0] && chs[0].dataset.ch);
    if (!force) for (const c of chs) if (c.offsetTop <= top) cur = c.dataset.ch;
    G.toc.querySelectorAll('.gd-tab').forEach((b) => { const on = b.dataset.ch === cur; b.setAttribute('aria-current', on ? 'true' : 'false'); if (on && NA.mobile && NA.mobile.mobile) b.scrollIntoView({ block: 'nearest', inline: 'nearest' }); });
  }
  G.show = function (chapter, query) {
    if (!G.dlg) build();
    if (NA.chrome && NA.chrome.toggleHelp) NA.chrome.toggleHelp(false);
    G.opener = document.activeElement;
    G.search.value = query || '';
    render();
    G.dlg.hidden = false; G.open = true;
    if (chapter) jump(chapter); else G.main.scrollTop = 0;
    // the search box on a computer; on a phone the keyboard would cover the guide, so the close button
    (touch() ? G.closeBtn : G.search).focus();
  };
  G.close = function () {
    if (!G.dlg || G.dlg.hidden) return;
    G.dlg.hidden = true; G.open = false;
    if (G.opener && G.opener.focus && document.contains(G.opener)) G.opener.focus();
  };
  G.toggle = function () { if (G.open) G.close(); else G.show(); };
  G.chapters = CHAPTERS;
  NA.guide = G;
})(window.NA);
